<?php
namespace App\Http\Controllers;
use App\Models\ItemTransfer;use App\Models\Product;use App\Models\Store;use App\Models\StorePosition;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\View\View;
class ItemTransferController extends Controller{public function index():View{$transfers=ItemTransfer::query()->leftJoin('stores as f','item_transfers.from_store_id','=','f.id')->leftJoin('stores as t','item_transfers.to_store_id','=','t.id')->select('item_transfers.*','f.name as from_store','t.name as to_store')->withSum('items as total_quantity','quantity')->latest('transfer_date')->paginate(20);return view('item-transfers.index',compact('transfers'));}public function create():View{return view('item-transfers.create',['nextNo'=>$this->next(),'stores'=>Store::where('is_active',true)->orderBy('name')->get(),'positions'=>StorePosition::where('is_active',true)->orderBy('name')->get(),'products'=>Product::where('is_active',true)->orderBy('part_no')->get(['id','part_no','name','unit_price'])]);}public function store(Request $r){$d=$r->validate(['transfer_date'=>['required','date'],'transfer_type'=>['required','string'],'from_store_id'=>['required','different:to_store_id','exists:stores,id'],'to_store_id'=>['required','exists:stores,id'],'remarks'=>['nullable','string'],'items'=>['required','array','min:1'],'items.*.product_id'=>['required','distinct','exists:products,id'],'items.*.from_position_id'=>['nullable','exists:store_positions,id'],'items.*.to_position_id'=>['nullable','exists:store_positions,id'],'items.*.quantity'=>['required','numeric','min:.01'],'items.*.unit_cost'=>['nullable','numeric','min:0']]);DB::transaction(function()use($d,$r){$total=collect($d['items'])->sum(fn($i)=>$i['quantity']*($i['unit_cost']??0));$t=ItemTransfer::create(collect($d)->except('items')->all()+['transfer_no'=>$this->next(),'total_amount'=>$total,'user_id'=>$r->user()->id]);$t->items()->createMany(collect($d['items'])->map(fn($i)=>$i+['amount'=>$i['quantity']*($i['unit_cost']??0)])->all());});return redirect()->route('item-transfers.index')->with('success','Item transfer saved successfully.');}private function next():string{return 'TRF-'.now()->format('ymd').'-'.str_pad((string)(ItemTransfer::whereDate('created_at',now()->toDateString())->count()+1),4,'0',STR_PAD_LEFT);}}
